class PlayerDetail(BaseModel):
    """
    A single player's profile with season stats, accolades, and (when the
    player is linked to a person) their cross-program career.
    """

    accolades: Any | None = Field(
        None, description="Awards and honors, when held.", title="Accolades"
    )
    bats: str | None = Field(
        None, description="Baseball and softball: 'L', 'R' or 'S'.", title="Bats"
    )
    career: Any | None = Field(
        None,
        description="When the player is linked to a person: one entry per school, in order, each with its own `stats_by_season` and `stats_totals`.",
        title="Career",
    )
    class_standing: ClassStanding | None = None
    class_year: str | None = Field(
        None,
        description="The class as the program published it ('Jr.', 'R-So.', 'Gr.'). Deprecated in that form: from the sunset the deprecation headers name, it carries `class_standing.label`. Read `class_year_published` for the string.",
        title="Class Year",
    )
    class_year_published: str | None = Field(
        None,
        description="The class exactly as the program published it.",
        title="Class Year Published",
    )
    conference: str | None = Field(None, title="Conference")
    division: str | None = Field(
        None, description="e.g. 'D1', 'D2', 'D3', 'NAIA', 'NJCAA-D1'.", title="Division"
    )
    eligibility: Eligibility | None = Field(
        None, description="Seasons left; null where we hold no reading yet."
    )
    first_name: str | None = Field(
        None,
        description="Given name, when the roster source published the name in split form; null when it published one undivided name (use `name`).",
        title="First Name",
    )
    gender: str | None = Field(None, description="'men' or 'women'.", title="Gender")
    headshot_url: str | None = Field(None, title="Headshot Url")
    height: str | None = Field(
        None, description="Formatted height, e.g. '6-2'.", title="Height"
    )
    height_inches: int | None = Field(None, title="Height Inches")
    high_school: str | None = Field(
        None, description="As the source printed it.", title="High School"
    )
    high_school_kind: HighSchoolKind | None = Field(
        None,
        description="What the `high_school` text names: 'high_school' (a school; see `secondary_school`), 'college' (a college the player attended before this one), 'club' (a club or academy program), 'homeschool', 'not_a_school', or 'unresolved' (we looked and could not tell which school, or which kind of place, it is). Null when there is no `high_school` text or it has not been classified yet. `high_school` itself is always the text the source printed.",
        examples=["high_school"],
        title="High School Kind",
    )
    home_city: str | None = Field(None, title="Home City")
    home_country: str | None = Field(None, title="Home Country")
    home_state: str | None = Field(None, title="Home State")
    hometown: str | None = Field(
        None, description="As published, e.g. 'Portland, OR'.", title="Hometown"
    )
    id: int | None = Field(
        None, description="Player id; use with GET /v1/players/{player_id}.", title="Id"
    )
    is_verified: bool | None = Field(
        None,
        description="True when the athlete has claimed this profile.",
        title="Is Verified",
    )
    jersey_number: str | None = Field(
        None, description="As published, e.g. '7' or '00'.", title="Jersey Number"
    )
    last_name: str | None = Field(
        None,
        description="Family name, including any generational suffix; null as for `first_name`.",
        title="Last Name",
    )
    major: str | None = Field(None, title="Major")
    minor: str | None = Field(None, title="Minor")
    name: str | None = Field(
        None,
        description="Full name in natural order, e.g. 'Jordan Rivera'.",
        title="Name",
    )
    person_id: int | None = Field(
        None,
        description="Cross-program person id; use with GET /v1/persons/{person_id}.",
        title="Person Id",
    )
    position: str | None = Field(
        None,
        description="The position as the school published it ('F', 'Fwd', 'Forward', 'M/F'). Spellings differ from school to school; read `positions` and `position_groups` for one value per sport.",
        title="Position",
    )
    position_groups: list[str] | None = Field(
        None,
        description="The broadest category of each of `positions`: baseball 'SS' is in 'INF', 'RHP' in 'P'; basketball 'PG' in 'GUARD'; ice hockey 'LW' in 'F'; football 'OT' in 'OL'. A sport whose vocabulary is flat (soccer, volleyball, lacrosse, field hockey) repeats `positions`. Null or [] exactly where `positions` is.",
        examples=[["MID"]],
        title="Position Groups",
    )
    positions: list[str] | None = Field(
        None,
        description="The standardized position or positions `position` names, in the sport's canonical vocabulary: the values GET /v1/filters/catalog lists for the player `position` field ('GK', 'DEF', 'MID', 'FWD' in soccer; 'PG', 'SS', 'OH', 'QB', ...). A list because a school can print two: soccer 'M/F' is ['MID', 'FWD']. Each value is one you can filter by, and a `position` filter matches the row by the same reading, so a player returned for `position=FWD` carries 'FWD' here. Null for a sport with no positions (tennis, golf, swimming and diving, track and field); [] where the sport has them and the published text names none (nothing published, a role such as 'Special Teams', a spelling not yet in the vocabulary).",
        examples=[["MID"]],
        title="Positions",
    )
    previous_school: str | None = Field(
        None,
        description="The school or schools the athlete came from, as their newest roster or profile page at this team lists them; several are joined with ' / ', e.g. 'Papillion La Vista H.S. / Iowa Western CC'.",
        title="Previous School",
    )
    region: str | None = Field(
        None,
        description="The association's region, for NJCAA and NCCAA teams: the team's region, e.g. 'NJCAA Region IV'. Null for every other team. A region is not a conference: an NJCAA team can have both.",
        title="Region",
    )
    season_stats: Any | None = Field(
        None,
        deprecated=True,
        description="Deprecated, removed on 2027-01-12: use `stats_by_season`, `stats_totals` and `track_bests`. An object keyed 'season_<year>' (and 'cumulative_null'), each a one-item list holding the season row.",
        title="Season Stats",
    )
    secondary_school: HighSchoolRef | None = Field(
        None,
        description="The registry school `high_school` names, when `high_school_kind` is 'high_school'; null otherwise.",
    )
    sport: str | None = Field(
        None,
        description="Sport, as in the request: 'soccer', 'track-and-field', ...",
        title="Sport",
    )
    sport_path: str | None = Field(
        None,
        description="Sport and gender as one key, e.g. 'womens-soccer'; matches teams, games and movements.",
        title="Sport Path",
    )
    stats_by_season: list[PlayerSeasonStats] | None = Field(
        None,
        description="One entry per season at this team, newest first.",
        title="Stats By Season",
    )
    stats_totals: dict[str, Any] | None = Field(
        None,
        description="Totals across `stats_by_season`: counting stats summed, headline rates recomputed from the totals, the rest null. Same fields as a season's `stats`.",
        title="Stats Totals",
    )
    team: str | None = Field(None, description="Team/school name.", title="Team")
    team_id: int | None = Field(
        None, description="Team id; use with GET /v1/teams/{team_id}.", title="Team Id"
    )
    team_logo_url: str | None = Field(None, title="Team Logo Url")
    throws: str | None = Field(
        None, description="Baseball and softball: 'L' or 'R'.", title="Throws"
    )
    track_bests: list[TrackBest] | None = Field(
        None,
        description="Track and field: best mark per event and discipline, across every season held and per season.",
        title="Track Bests",
    )


